const plot = document.querySelector('#gallery-interference');
plot.setAttribute('default-axes-on', 'false');
plot.setAttribute('controls', 'false');
plot.setAttribute('xpadding', '4');
plot.setAttribute('ypadding', '4');
plot.setAttribute('xmin', '-5');
plot.setAttribute('xmax', '5');
plot.setAttribute('ymin', '-3');
plot.setAttribute('ymax', '3');
const still = matchMedia('(prefers-reduced-motion: reduce)').matches;
plot.drawingLoop = () => {
  const ctx = plot.ctx;
  const t = still ? 0 : performance.now() / 600;
  const sourceX = plot.mouseX ?? 2;
  const sourceY = plot.mouseY ?? 0;
  const cols = 64, rows = 36;
  const w = plot.canvas.width / cols;
  const h = plot.canvas.height / rows;
  ctx.save();
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const x = plot.scaleXInverse((col + 0.5) * w);
      const y = plot.scaleYInverse((row + 0.5) * h);
      const a = Math.sin(5 * Math.hypot(x + 2, y) - t);
      const b = Math.sin(5 * Math.hypot(x - sourceX, y - sourceY) - t);
      const value = (a + b + 2) / 4;
      ctx.fillStyle = `hsl(${235 - value * 200}, 75%, ${15 + value * 55}%)`;
      ctx.fillRect(col * w, row * h, w + 1, h + 1);
    }
  }
  ctx.restore();
};

sunflower.code:
const plot = document.querySelector('#gallery-sunflower');
plot.setAttribute('default-axes-on', 'false');
plot.setAttribute('controls', 'false');
plot.setAttribute('xpadding', '4');
plot.setAttribute('ypadding', '4');
plot.setAttribute('xmin', '-1.2');
plot.setAttribute('xmax', '1.2');
plot.setAttribute('ymin', '-1.2');
plot.setAttribute('ymax', '1.2');
plot.drawingLoop = () => {
  const ctx = plot.ctx;
  const goldenAngle = Math.PI * (3 - Math.sqrt(5));
  const angle = goldenAngle + (plot.mouseX ?? 0) * 0.015;
  // Preserve a round garden even in a wide canvas.
  const radius = Math.min(plot.canvas.width, plot.canvas.height) * 0.44;
  const cx = plot.scaleX(0), cy = plot.scaleY(0);
  ctx.save();
  ctx.fillStyle = '#122d2b';
  ctx.fillRect(0, 0, plot.canvas.width, plot.canvas.height);
  for (let i = 1; i <= 450; i++) {
    const r = radius * Math.sqrt(i / 450);
    const theta = i * angle;
    ctx.fillStyle = `hsl(${30 + i / 5}, 80%, ${70 - i / 18}%)`;
    ctx.beginPath();
    ctx.arc(cx + r * Math.cos(theta), cy + r * Math.sin(theta),
      2 + 2 * Math.sqrt(i / 450), 0, 2 * Math.PI);
    ctx.fill();
  }
  ctx.restore();
};

